// Legacy tutorial redirect check for both deployment paths.
//
// The old marker.golf tutorial URLs are kept as real HTML redirect pages,
// generated by src/legacy-redirects.njk from src/_data/legacyRedirects.json
// (GitHub Pages ignores _redirects). For PATHPREFIX=/ and PATHPREFIX=/marker-site/,
// builds the site into a temporary folder and checks that:
//   - every required legacy path is mapped once and generates a folder index
//     page, so it works with or without a trailing slash;
//   - the canonical link, meta refresh, location.replace() and the visible
//     fallback link all point at the same destination: the build's prefix plus
//     the new path, with the prefix exactly once and never /marker-site/ in the
//     root build (no canonical domain is configured, so the canonical is the
//     destination under the build's own prefix);
//   - the destination exists and is a real page, not another redirect (no
//     loops or chains), and no legacy path redirects to itself;
//   - each page has a language, a heading and a link with text.
//
// Exits non-zero and lists every problem.
// Usage: npm run check:redirects

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const PREFIXES = ['/', '/marker-site/']
const REQUIRED = [
  '/tutorials/gettingstarted/',
  '/tutorials/firstscorecard/',
  '/tutorials/posting/',
  '/tutorials/createevent/',
  '/tutorials/eventaddplayers/',
  '/tutorials/eventcreatescorecards/',
  '/tutorials/eventaddgames/',
  '/tutorials/eventscoring/',
  '/tutorials/sidegames/'
]
const redirects = JSON.parse(fs.readFileSync(path.join(ROOT, 'src/_data/legacyRedirects.json'), 'utf8'))
const problems = []

// Mapping ----------------------------------------------------------------------
const froms = redirects.map(r => r.from)
for (const required of REQUIRED) if (!froms.includes(required)) problems.push(`no redirect for ${required}`)
for (const from of new Set(froms)) if (froms.filter(f => f === from).length > 1) problems.push(`${from} is mapped more than once`)
for (const { from, to, title } of redirects) {
  for (const [name, value] of [['from', from], ['to', to]]) {
    if (!/^\/[a-z0-9/-]+\/$/.test(value)) problems.push(`${name} ${value}: must be a lowercase root-relative path ending in /`)
    if (value.includes('/marker-site/')) problems.push(`${name} ${value}: must not include a path prefix`)
  }
  if (from === to) problems.push(`${from} redirects to itself`)
  if (froms.includes(to)) problems.push(`${from} -> ${to}: destination is another legacy redirect`)
  if (!title) problems.push(`${from}: no title for the fallback link`)
}

// Builds -------------------------------------------------------------------------
const attr = (html, re) => (html.match(re) || [])[1]
const isRedirectPage = html => /http-equiv="refresh"/i.test(html)

function checkBuild (prefix) {
  const out = fs.mkdtempSync(path.join(os.tmpdir(), 'marker-site-redirects-'))
  try {
    const build = spawnSync(path.join(ROOT, 'node_modules/.bin/eleventy'), [`--output=${out}`, '--quiet'], {
      cwd: ROOT, encoding: 'utf8', env: { ...process.env, PATHPREFIX: prefix }
    })
    if (build.status !== 0) {
      problems.push(`build with PATHPREFIX=${prefix} failed:\n${build.stderr || build.stdout}`)
      return 0
    }
    for (const { from, to } of redirects) {
      const where = `[${prefix}] ${from}`
      const file = path.join(out, from, 'index.html')
      if (!fs.existsSync(file)) { problems.push(`${where}: no page generated`); continue }
      // A file at the slash-less path would shadow the folder on static hosts.
      for (const shadow of [path.join(out, from.slice(0, -1)), path.join(out, `${from.slice(0, -1)}.html`)]) {
        if (fs.existsSync(shadow) && fs.statSync(shadow).isFile()) problems.push(`${where}: ${path.relative(out, shadow)} shadows the redirect folder`)
      }
      const html = fs.readFileSync(file, 'utf8')
      const expected = prefix + to.slice(1)
      const found = {
        canonical: attr(html, /<link rel="canonical" href="([^"]*)"/),
        refresh: attr(html, /<meta http-equiv="refresh" content="0; url=([^"]*)"/),
        script: attr(html, /location\.replace\("([^"]*)"\)/),
        link: attr(html, /<main>[\s\S]*?<a href="([^"]*)">[^<]+<\/a>/)
      }
      for (const [name, value] of Object.entries(found)) {
        if (value !== expected) problems.push(`${where}: ${name} is ${value ?? 'missing'}, expected ${expected}`)
      }
      if (prefix !== '/' && html.includes(prefix + prefix.slice(1))) problems.push(`${where}: duplicated path prefix`)
      if (prefix === '/' && html.includes('/marker-site/')) problems.push(`${where}: root build embeds /marker-site/`)
      if (!/<html lang="en">/.test(html) || !/<h1>[^<]+<\/h1>/.test(html)) problems.push(`${where}: missing lang or heading`)
      const target = path.join(out, to, 'index.html')
      if (!fs.existsSync(target)) problems.push(`${where}: destination ${to} does not exist`)
      else if (isRedirectPage(fs.readFileSync(target, 'utf8'))) problems.push(`${where}: destination ${to} is itself a redirect`)
    }
    return redirects.length
  } finally {
    fs.rmSync(out, { recursive: true, force: true })
  }
}

for (const prefix of PREFIXES) {
  const checked = checkBuild(prefix)
  if (checked) console.log(`[redirects] PATHPREFIX=${prefix}: ${checked} legacy redirect pages checked`)
}
if (problems.length) {
  console.error(`[redirects] ${problems.length} problem(s):\n${problems.map(p => `  - ${p}`).join('\n')}`)
  process.exit(1)
}
console.log('[redirects] every legacy tutorial path redirects once to an existing page under both prefixes')
